package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func arrayMultiply(arr []int) int {
	res := 1
	for _, v := range arr {
		res *= v
	}
	return res
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	n, _ := reader.ReadString('\n')
	n = strings.TrimSpace(n)
	nLength := len(n)

	if nLength == 1 {
		fmt.Print(n)
		return
	}

	if nLength > 1 {
		allNine := true
		for i := 1; i < nLength; i++ {
			if n[i] != '9' {
				allNine = false
				break
			}
		}
		if allNine {
			arr := make([]int, nLength)
			for i, ch := range n {
				arr[i] = int(ch - '0')
			}
			fmt.Print(arrayMultiply(arr))
			return
		}
	}

	nArr := make([]int, nLength)
	for i, ch := range n {
		nArr[i] = int(ch - '0')
	}

	maxVal := arrayMultiply(nArr)

	for i := 0; i < nLength-1; i++ {
		arr := make([]int, nLength)
		copy(arr, nArr)
		arr[i] = arr[i] - 1
		for j := i + 1; j < nLength; j++ {
			arr[j] = 9
		}
		for j := nLength - 1; j > 0; j-- {
			if arr[j] == 0 {
				arr[j] = 9
				arr[j-1]--
			}
			if arr[j] == -1 {
				arr[j] = 9
				arr[j-1]--
			}
		}
		if arr[0] == 0 {
			arr = arr[1:]
		}
		val := arrayMultiply(arr)
		if val > maxVal {
			maxVal = val
		}
	}

	fmt.Print(maxVal)
}

